Q: How Can My App React to Power Connecting/Disconnecting Even When Closed? A: <pre><code>class PowerConnectionWorker(appContext: Context, workerParams: WorkerParameters):
    Worker(appContext, workerParams) {

    override fun doWork(): Result {
        // Your logic here (e.g., sync data, send notification, update local DB)
        Log.d(&quot;PowerWorker&quot;, &quot;Power state change detected! App is executing in background.&quot;)

        // Return success so the OS knows the task is finished
        return Result.success()
    }
}
</code></pre>
<pre><code>fun schedulePowerTask(context: Context) {
    // Define constraints: The task will only run when the device is charging
    val constraints = Constraints.Builder()
        .setRequiresCharging(true) 
        .build()

    // Use PeriodicWork if you want to check/react consistently
    // Note: Minimum interval for PeriodicWork is 15 minutes
    val powerRequest = PeriodicWorkRequestBuilder&lt;PowerConnectionWorker&gt;(15, TimeUnit.MINUTES)
        .setConstraints(constraints)
        .build()

    WorkManager.getInstance(context).enqueueUniquePeriodicWork(
        &quot;PowerStatusWork&quot;,
        ExistingPeriodicWorkPolicy.KEEP, 
        powerRequest
    )
}
</code></pre>
